package gin

import (
	"fmt"
	"math/rand"
	"regexp"
	"strings"
	"testing"
)

func routeRegexp(path string) (*regexp.Regexp, []string) {
	segs := strings.Split(path, "/")
	parts := make([]string, 0, len(segs))
	var names []string
	for _, s := range segs {
		if s == "" {
			parts = append(parts, "")
			continue
		}
		switch s[0] {
		case ':':
			names = append(names, s[1:])
			parts = append(parts, "([^/]+)")
		case '*':
			names = append(names, s[1:])
			parts = append(parts, "(.*)")
		default:
			parts = append(parts, regexp.QuoteMeta(s))
		}
	}
	return regexp.MustCompile("^" + strings.Join(parts, "/") + "$"), names
}

var statics = []string{"a", "b", "ab", "abc", "x", "ax", "bx", "cd", "c", "d", "aa", "bb", "cc", "ba"}
var paramNames = []string{"p", "q", "r", "name", "id"}

func randRoute(rnd *rand.Rand) string {
	n := 1 + rnd.Intn(4)
	segs := make([]string, 0, n)
	for i := 0; i < n; i++ {
		last := i == n-1
		r := rnd.Intn(100)
		switch {
		case last && r < 8:
			segs = append(segs, "*"+paramNames[rnd.Intn(len(paramNames))])
		case r < 35:
			segs = append(segs, ":"+paramNames[rnd.Intn(len(paramNames))])
		default:
			segs = append(segs, statics[rnd.Intn(len(statics))])
		}
	}
	return "/" + strings.Join(segs, "/")
}

func randPath(rnd *rand.Rand) string {
	n := 1 + rnd.Intn(5)
	segs := make([]string, 0, n)
	for i := 0; i < n; i++ {
		r := rnd.Intn(100)
		if r < 80 {
			segs = append(segs, statics[rnd.Intn(len(statics))])
		} else {
			segs = append(segs, fmt.Sprintf("v%d", rnd.Intn(5)))
		}
	}
	p := "/" + strings.Join(segs, "/")
	if rnd.Intn(6) == 0 {
		p += "/"
	}
	return p
}

