func routeRegexp(path string) (*regexp.Regexp, []string) {
	segs := strings.Split(path, "/")
	parts := make([]string, 0, len(segs))
	var names []string
	for _, s := range segs {
		if s == "" {
			parts = append(parts, "")
			continue
		}
		switch s[0] {
		case ':':
			names = append(names, s[1:])
			parts = append(parts, "([^/]+)")
		case '*':
			names = append(names, s[1:])
			parts = append(parts, "(.*)")
		default:
			parts = append(parts, regexp.QuoteMeta(s))
		}
	}
	return regexp.MustCompile("^" + strings.Join(parts, "/") + "$"), names
}

