		rnd := rand.New(rand.NewSource(seed))
		nRoutes := 1 + rnd.Intn(12)
		var routes []string
		root := &node{}
		for i := 0; i < nRoutes; i++ {
			p := randRoute(rnd)
			dup := false
			for _, r := range routes {
				if r == p {
					dup = true
				}
			}
			if dup {
				continue
			}
			ok := func() (ok bool) {
				defer func() {
					if rec := recover(); rec != nil {
						ok = false
					}
				}()
				root.addRoute(p, HandlersChain{func(c *Context) { fakeHandlerValue = p }})
				return true
			}()
			if ok {
				routes = append(routes, p)
			}
		}
		if len(routes) == 0 {
			continue
		}
		reMap := map[string]*regexp.Regexp{}
		nsMap := map[string][]string{}
		for _, r := range routes {
			re, ns := routeRegexp(r)
			reMap[r] = re
			nsMap[r] = ns
		}
		for i := 0; i < 400; i++ {
			p := randPath(rnd)
			var exp []string
			for _, r := range routes {
				if reMap[r].MatchString(p) {
					exp = append(exp, r)
				}
			}
			params := getParams()
			value := root.getValue(p, params, getSkippedNodes(), false)
			if value.handlers == nil {
				if len(exp) == 1 {
					nMiss++
					if nMiss <= 15 {
						t.Logf("MISS seed=%d routes=%v path=%q expected %q", seed, routes, p, exp[0])
					}
				}
				continue
			}
			fakeHandlerValue = ""
			value.handlers[0](nil)
			got := fakeHandlerValue
			if !reMap[got].MatchString(p) {
				nFalsePos++
				if nFalsePos <= 15 {
					t.Errorf("FALSEPOS seed=%d routes=%v path=%q matched %q", seed, routes, p, got)
				}
				continue
			}
			if len(exp) == 1 && exp[0] != got {
				nWrong++
				if nWrong <= 15 {
					t.Errorf("WRONGROUTE seed=%d routes=%v path=%q matched %q expected %q", seed, routes, p, got, exp[0])
				}
			}
			// positional param comparison against the matched route's regexp
			m := reMap[got].FindStringSubmatch(p)
			names := nsMap[got]
			var gotVals []string
			if value.params != nil {
				for _, pr := range *value.params {
					gotVals = append(gotVals, pr.Value)
				}
			}
			if len(gotVals) != len(names) {
				nParam++
				if nParam <= 15 {
					t.Errorf("PARAMCOUNT seed=%d routes=%v path=%q matched %q got %v want %v", seed, routes, p, got, gotVals, m[1:])
				}
				continue
			}
			for k := range names {
				want := m[k+1]
				if got == "" {
					continue
				}
				// catch-all values include the leading '/'
				if strings.HasPrefix(names[k], "") && strings.Contains(got, "*") {
				}
				if gotVals[k] != want && gotVals[k] != "/"+want {
					nParam++
					if nParam <= 15 {
						t.Errorf("PARAMVAL seed=%d routes=%v path=%q matched %q param %q got %q want %q", seed, routes, p, got, names[k], gotVals[k], want)
					}
				}
			}
		}
	}
	t.Logf("summary: falsepos=%d wrongroute=%d param=%d miss=%d", nFalsePos, nWrong, nParam, nMiss)
}

